    if (typeof chunk !== 'string') throw new TypeError('chunk must be a string');
    if (ended) throw new Error('cannot push after end');
    const records = [];
    let i = 0;
    if (!started && chunk.length > 0) {
      started = true;
      if (chunk.charCodeAt(0) === 0xfeff) i = 1;
    }
    for (; i < chunk.length; i++) {
      const ch = chunk[i];
      const wasCR = prevCR;
      prevCR = ch === '\r';
      if (ch === '\r' || (ch === '\n' && !wasCR)) line++;

      if (skipLF) {
        skipLF = false;
        if (ch === '\n') continue;
      }

      if (state === QUOTED) {
        if (ch === '"') state = QUOTE_IN_QUOTED;
