        continue;
      }
      if (state === QUOTE_IN_QUOTED) {
        if (ch === '"') {
          field += '"';
          state = QUOTED;
          continue;
        }
        state = AFTER_CLOSE;
      }

      if (ch === delimiter) {
        row.push(field);
        field = '';
        rowStarted = true;
        state = FIELD_START;
      } else if (ch === '\n' || ch === '\r') {
        endRecord(records);
        skipLF = ch === '\r';
      } else if (state === AFTER_CLOSE) {
        throw new SyntaxError(`Unexpected character after closing quote at line ${line}`);
      } else if (state === FIELD_START && ch === '"') {
        rowStarted = true;
        state = QUOTED;
      } else {
        field += ch;
        rowStarted = true;
        state = UNQUOTED;
      }
    }
    return records;
  }

  function end() {
    if (ended) return [];
    ended = true;
    if (state === QUOTED) throw new SyntaxError(`Unterminated quoted field at line ${line}`);
    const records = [];
    if (rowStarted) endRecord(records);
    return records;
  }

  return { push, end };
