'use strict';
const assert = require('node:assert/strict');
const { createParser, parse } = require('./src/csv');

const eq = (input, expected, opts) => assert.deepEqual(parse(input, opts), expected, JSON.stringify(input));
eq('', []);
eq('\ufeff', []);
eq('\n', [['']]);
eq('\n\n', [[''], ['']]);
eq('a\n', [['a']]);
eq('a\r\nb\rc', [['a'], ['b'], ['c']]);
eq('\ufeffa,\ufeffb', [['a', '\ufeffb']]);
eq('a"b,"c""d"', [['a"b', 'c"d']]);
eq('"x\r\ny\rz"', [['x\r\ny\rz']]);
eq('a;b,c', [['a', 'b,c']], { delimiter: ';' });
eq('""', [['']]);
eq('a,b\n1\n', [{ a: '1', b: '' }], { header: true });
eq('', [], { header: true });
const lineOf = fn => { try { fn(); } catch (e) { assert.ok(e instanceof SyntaxError); return Number(/line (\d+)/.exec(e.message)[1]); } assert.fail('no throw'); };
assert.equal(lineOf(() => parse('"a" ,b')), 1);
assert.equal(lineOf(() => parse('"a\r\nb\nc\rd" x')), 4);
assert.equal(lineOf(() => parse('x\r\n"abc\n')), 3);
for (const d of [undefined, ',', '\t']) createParser({ delimiter: d });
for (const d of ['', '"', '\r', '\n', ',,', 1, null]) assert.throws(() => createParser({ delimiter: d }), RangeError);

// Every two-way and per-character split must match whole parse, incl. line numbers.
const inputs = ['\ufeffa,"b""c"\r\n"d\r\ne",f\r\r\n', 'x,"y\r\n"\r\nz', '"q""', '\ud83d\ude00,"\ud83d\ude00"\n'];
for (const input of inputs) {
  let whole; try { whole = parse(input); } catch (e) { whole = e.message; }
  const splits = [[...input].map((_, i) => i)];
  for (let k = 0; k <= input.length; k++) splits.push([k]);
  splits.push(Array.from({ length: input.length }, (_, i) => i));
  for (const cuts of splits) {
    const p = createParser();
    let out = [];
    let prev = 0;
    try {
      for (const c of [...cuts, input.length]) { out = out.concat(p.push(input.slice(prev, c))); p.push(''); prev = c; }
      out = out.concat(p.end());
    } catch (e) { out = e.message; }
    assert.deepEqual(out, whole, JSON.stringify([input, cuts]));
  }
}
// Immediate emission and lifecycle.
const p = createParser();
assert.deepEqual(p.push('a\r'), [['a']]);
assert.deepEqual(p.push('\nb'), []);
assert.deepEqual(p.end(), [['b']]);
assert.deepEqual(p.end(), []);
assert.throws(() => p.push(''), e => e.constructor === Error);
assert.throws(() => createParser().push(1), TypeError);
assert.throws(() => { const q = createParser(); q.push('"a'); q.end(); }, SyntaxError);
console.log('ok');

